-- GENERATED by `wfj generate` from data/gossip/gossip-39.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["39002a0adccf3450"] = { "Non avrei potuto dirlo meglio.", "." },
  ["39042f0631824a05"] = { "E ora la prossima corsa: l'auto sarà ancora PIÙ VELOCE di prima!", "." },
  ["3904d20449cf501c"] = { "Non è un pollo, e no, non puoi accarezzarlo. Ora vattene, prima che ti faccia vedere il suo becco più da vicino.", "." },
  ["39088317170164cb"] = { "Lo spirito di %s è libero...", "." },
  ["390d5f06476b3dc6"] = { "Come desidera, signore.", "." },
  ["390de5d71c51419c"] = { "Ce n'è uno nella caserma sul lato est di ⟦Razor Hill=Tranciacolle⟧. Cerca Rawrk.", "." },
  ["391199d9f6573f58"] = { "Muori nel nome della Dama Oscura, {name}.", "." },
  ["3914bb1499561a26"] = { "Ciao! Rimuovi qui gli effetti della resurrezione!", "." },
  ["3916d6a80b46b4df"] = { "Un sonno ristoratore è assicurato nei letti che la locandiera Keldamyr tiene nella locanda di Dolanaar.", "." },
  ["3917b6ff1fc5372b"] = { "Come procede la battaglia per sabotare i calderoni?", "." },
  ["391bfd6a82e318b6"] = { "Il ragazzo aveva raccolto Brandicenere e l'aveva conficcata nel cuore di suo padre mentre gli voltava le spalle. Le sue ultime parole mi perseguiteranno per sempre: \"Che cosa hai fatto, Renault? Perché l'hai fatto?\"", "." },
  ["391faa812118f853"] = { "Grazie, {name}. Venderò quelle bevande in un attimo!", "." },
  ["392040d3ee2aa369"] = { "Sì, parlo una lingua che capisci, {race}. Non siamo animali, eppure la maggior parte della tua gente continua a trattarci come tali! Ma le nostre differenze impallidiscono di fronte alla tragedia che ha colpito questa terra. Ti prego, metti da parte le tue divergenze con la mia gente e ascolta la mia ultima supplica.\n\nHo raggiunto questa terra per sanare ciò che potevo, e ora tutto sarà stato vano se non potrai aiutarmi. Ti chiedo questo aiuto con i miei ultimi respiri.", "." },
  ["3920fb6119314c32"] = { "Non ha lasciato nemmeno gli stivali...", "." },
  ["393095dce617b77d"] = { "Ti porto il ⟦Libram of Rumination=Compendio sulla Meditazione⟧.", "." },
  ["3936cb1262a8c284"] = { "La West Frostwolf Tower protegge la porta tra il ⟦Frostwolf Village=Villaggio dei Lupi Bianchi⟧ e la ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧.\n\nÈ controllata dall'⟦Alliance=Alleanza⟧.", "." },
  ["3937083406ba5c64"] = { "Ci aiuterai in quest'ora di grande bisogno nel ⟦Arathi Basin=Bacino d'Arathi⟧, {class}? L'occasione di ottenere onore e reputazione è più grande che mai, e il tuo aiuto contribuirà di certo a ribaltare le sorti contro i ⟦The Defilers=Profanatori⟧. Possiamo contare su di te?", "." },
  ["393a3d02969cd19f"] = { "⟦Darrowshire=Borgo di Darrow⟧, alle armi! Il Flagello avanza!", "." },
  ["39484f9bad745b93"] = { "Alla fine intervenne il gran caposquadra Puzik Gallywix, che portò il veleno in eccesso nella sua torre, qui nella ⟦Sludge Fen=Palude Fangosa⟧, per studiare e analizzare la natura instabile delle tossine. Infine si decise di condividere il segreto del veleno con la ⟦Defias Brotherhood=Fratellanza dei Defias⟧ in cambio di una grossa scorta di un veleno stabile e utilizzabile.\n\nKlaven Mortwake della ⟦Defias Brotherhood=Fratellanza dei Defias⟧ ebbe il compito di alterare le proprietà chimiche della miscela di Zanzil.", "." },
  ["394f695ae06ca7e2"] = { "Devi ricordare che, sebbene questo regno sia la nostra casa da millenni, saremo sempre un po' estranei a questo luogo. Non siamo nel mondo terrestre che ha dato vita al nostro popolo. Siamo nel regno di ⟦Skywall=Celaria⟧, il piano elementale dell'aria. \r\n\nSiamo giunti qui come ospiti di spiriti con cui, in epoche passate, abbiamo trovato affinità. Ora che noi Shen'dorei ci ritroviamo privi della loro presenza, e forse della loro protezione, non si può dire come ci vedranno gli altri abitanti di questo piano.", "." },
  ["395015aa3a257b9c"] = { "Fatti sotto!", "." },
  ["39501d3095720bd8"] = { "Come fai a sapere tutto questo?", "." },
  ["3954c6570b408f76"] = { "Non posso addestrare <un/una> {class} come te.", "." },
  ["395717e5dc379a81"] = { "Mi piace proprio sedermi qui fuori ad ascoltare i suoni del Grande Mare. Oh, cosa? Sì, c'è una nave che ti porterà a ⟦Menethil Harbor=Porto di Menethil⟧. Attracca qui di tanto in tanto.", "." },
  ["39642dd3a5b0ba9d"] = { "È fatta. Ho la tua arma, {name}.", "." },
  ["39663a88c21400bd"] = { "Quando vidi per la prima volta i non morti piansi, perché non riuscivo a immaginare il loro orrore e la loro solitudine. Fu allora che la Madre Terra mi parlò; cantò nel mio sangue. E mi disse: «Salvali.»", "." },
  ["3967bd7a6a259e44"] = { "Abbiamo più di un nemico a ⟦Silithus=Silitus⟧, {name}.\n\nMentre l'attenzione di tutti è concentrata sui silitidi, io e mio fratello maggiore teniamo d'occhio quei pazzi del ⟦Twilight's Hammer=Martello del Crepuscolo⟧.", "." },
  ["39695046694833fd"] = { "Scusa se ci ho messo tanto ad arrivare. Volevo che fosse presente anche lady Proudmoore.", "." },
  ["396bf8870895daf5"] = { "Ancora un sorso della vecchia acqua di fuoco e potrò parlare. Hic! Salute!", "." },
  ["3973a01fb757490c"] = { "Le grandi guerre saranno anche finite, per ora, ma dobbiamo comunque tenere affilate le nostre abilità!", "." },
  ["3973a9236a4a3a79"] = { "Avvistata una banda da guerra Qiraji!", "." },
  ["3977c120b955c77a"] = { "C'è una cassetta della posta fuori dalla banca, che troverai al centro di Darnassus.", "." },
  ["39867dbfd02f7724"] = { "<Benvenuto/Benvenuta>, <fratello/sorella> <mio/mia>. Se sei qui per addestrarti, sarò felice di farlo.\n\nSiamo i custodi dell'equilibrio, ora e per sempre, come ci ha insegnato Cenarius. Non dimenticarlo mai.", "." },
  ["39875d656fd5cc2d"] = { "Gli scheletri hanno superato la Hall of Lights! Distruggeteli!", "." },
  ["398b8d864fad109b"] = { "{name}! Le note nella borsa che ti ho dato bastavano per trovare Metzen? Odio pensare a cosa potrebbero fargli quei crudeli delinquenti... ma non possiamo assolutamente permetterci di pagare un riscatto così esorbitante!", "." },
  ["398f247bf8dc7ef0"] = { "<Caro/Cara> amic<o/a>, li onori con la tua attenta veglia. Sei <saldo/salda> nella tua lealtà. Non dubito nemmeno per un istante che saresti pront<o/a> a compiere per il tuo popolo un sacrificio grande quanto quello degli eroi ai cui piedi ti trovi.", "." },
  ["39913f2fe247d3cf"] = { "Per catturare Gahz'ranka ti servirà una speciale Esca per Fanguzzola. Le preparo con le mie mani!\n\nMa non ti basta l'esca: ti servono anche delle fanguzzole... devi metterle nell'esca perché emani un bel tanfo!\n\nQuando avrai le fanguzzole, getta l'esca da Pagle's Point, a ⟦Zul'Gurub=Zul'gurub⟧... poi prenditi da bere e aspetta... ma non troppo, perché Gahz'ranka arriverà di sicuro a gran passi!", "." },
  ["3995b69dbdb975fa"] = { "Aspetterò.", "." },
  ["399635fb3fadb3d4"] = { "Muori nel nome della ⟦Defias Brotherhood=Fratellanza dei Defias⟧!", "." },
  ["399c22666afbc4e4"] = { "Bene. Per mettere in atto il mio piano, dobbiamo prima creare una pietra vitale. Sei <pronto/pronta> ad agire?", "." },
  ["39ac2050cdfd91b0"] = { "Tanti anni di battaglie e di schiavitù... è bello avere di nuovo una casa.", "." },
  ["39b625070a5e3627"] = { "È il materiale di base usato nella sintesi delle razze. Come fondamento per la sintesi dei Terrigeni fu usata una sezione della crosta di Azeroth, anziché la solita base di biomassa usata dai Creatori.\n\nLe ricerche sulla composizione del mondo portarono i Creatori a teorizzare che si potesse sintetizzare un essere potenziato, che incarnasse la resilienza dell'essenza di questo mondo. Ci si riuscì scegliendo come fondamento una miscela dei vari composti del nucleo di pietra di Azeroth.", "." },
  ["39bebbd38d680a69"] = { "Trascrivi la tavoletta.", "." },
  ["39c50943e4d33cea"] = { "Pensi mai a qualcosa che non sia combattere? Potrei girarti intorno sul rettilineo!", "." },
  ["39db41bad090d69c"] = { "Paladino", "." },
  ["39dc015d2fe1a929"] = { "Gli orchi sono più svegli di quei corrieri! Dove diavolo sono finiti?", "." },
  ["39e4c70b5fdb67db"] = { "Se non fosse per il Torvo Beone, probabilmente passerei il mio tempo libero a strappare le ali ai draghetti.", "." },
  ["39eaac2381b583e9"] = { "Con tutte le viti che Bronk ha stretto, credo che qualcuna delle sue si sia allentata, se capisci cosa intendo. Comunque ha ancora un'ottima testa per progettare i congegni più strampalati. Dovresti andarlo a trovare allo ⟦Steelgrill's Depot=Scalo di Grigliafredda⟧.", "." },
  ["39f7f622cbfec10a"] = { "Mentre vagavo per il cratere dopo lo schianto, mi è tornata in mente una cosa che mi avevano detto una volta... «Sali, sali sul monte che hai davanti», diceva la voce nella mia testa.\n\nÈ dandole ascolto che mi ritrovo qui, {name}!", "." },
  ["39f8fba5bc4dffde"] = { "Devi aver raggiunto il livello Osannato con gli umani di ⟦Stormwind=Roccavento⟧ prima che ti insegni l'Equitazione, {class}.", "." },
  ["39fe5612e4b10883"] = { "Mi serve aiuto!", "." },
})
